// tracer: creates folders inside this resource (logs/<resource>, backups). FXServer's Lua cannot create a folder, and
// io.open cannot create a file in a folder that does not exist. Node can, inside the resource's own folder.
const fs = require('fs');
const path = require('path');

const root = path.resolve(GetResourcePath(GetCurrentResourceName()));

exports('mkdirp', (rel) => {
    if (typeof rel !== 'string') return 'bad path';
    const full = path.resolve(root, rel);
    if (full !== root && !full.startsWith(root + path.sep)) return 'outside the resource';
    try {
        fs.mkdirSync(full, { recursive: true });
        return 'ok';
    } catch (e) {
        return String(e && e.message || e);
    }
});

