// Match HUD, result card and ranking. The UI never decides anything: the arm position, the stamina and the
// result are the ones the server sent.
const resource = typeof GetParentResourceName === 'function' ? GetParentResourceName() : 'xex_armwrestling';
const $ = (id) => document.getElementById(id);

let T = {};
let rankingOpen = false;
let goTimer = null;
let watchTimer = null;
let spectating = false;

const fmt = (s, ...args) => args.reduce((out, a) => out.replace('%s', a), s || '');
const t = (key, ...args) => fmt(T[key] ?? '', ...args);
const money = (n) => '$' + Math.round(n || 0).toLocaleString('en-US');
const seconds = (ms) => (Math.max(0, ms || 0) / 1000).toFixed(1) + ' s';
const pct = (n) => Math.max(0, Math.min(1, Number(n) || 0)) * 100 + '%';

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined && text !== null) node.textContent = text;
  return node;
}

function post(name, body = {}) {
  return fetch(`https://${resource}/${name}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=UTF-8' },
    body: JSON.stringify(body),
  }).catch(() => {});
}

function applyTexts(texts) {
  T = texts || {};
  document.querySelectorAll('[data-t]').forEach((node) => (node.textContent = t(node.dataset.t)));
}

function applyUi(ui) {
  if (!ui) return;
  const hex = /^#?([0-9a-f]{6})$/i.exec(ui.accent || '');
  if (hex) {
    const n = parseInt(hex[1], 16);
    document.documentElement.style.setProperty('--accent', '#' + hex[1]);
    document.documentElement.style.setProperty('--accent-rgb', `${n >> 16}, ${(n >> 8) & 255}, ${n & 255}`);
  }
  $('brand').textContent = ui.brand || t('ui_brand');
  $('key-push').textContent = ui.keys?.push ?? 'E';
  $('key-leave').textContent = ui.keys?.leave ?? 'X';
  $('hint-push').textContent = t('ui_hint_push');
  $('hint-leave').textContent = t('ui_hint_leave');
  const zone = pct(ui.winAt ?? 0.1);
  $('zone-win').style.width = zone;
  $('zone-lose').style.width = zone;
  document.querySelectorAll('[data-stamina]').forEach((node) => (node.hidden = ui.stamina === false));
}

// Division badge: bronze, silver, gold, diamond or champion, in its colour
function badge(division, color) {
  if (!division) return null;
  const chip = el('span', 'badge ' + division, t('div_' + division));
  if (color) {
    chip.style.color = color;
    chip.style.borderColor = color;
  }
  return chip;
}

// MATCH ------------------------------------------------------------------------------------------

function setArm(grade) {
  const g = Math.max(0, Math.min(1, Number(grade) || 0));
  $('arm-marker').style.left = g * 100 + '%';
  const fill = $('arm-fill');
  fill.style.left = Math.min(g, 0.5) * 100 + '%';
  fill.style.width = Math.abs(g - 0.5) * 100 + '%';
  fill.classList.toggle('behind', g < 0.5);
}

function setStamina(id, value) {
  const bar = $(id);
  bar.style.width = pct(value);
  bar.classList.toggle('low', Number(value) < 0.25);
}

function openMatch(info) {
  clearTimeout(watchTimer);
  spectating = false;
  $('hud').classList.remove('spectating');
  $('hud-watching').hidden = true;
  const rival = info.side === 'a' ? 'b' : 'a';
  $('hud-me').textContent = info.names?.[info.side] ?? '';
  $('hud-rival').textContent = info.names?.[rival] ?? '';
  $('hud-pot').textContent = info.bet > 0 ? t('ui_pot', money(info.bet * 2)) : t('ui_friendly');
  $('hud-ranked').textContent = info.ranked ? t('ui_ranked') : t('ui_unranked');
  $('hud-ranked').classList.toggle('on', !!info.ranked);
  $('hud-clock').textContent = '';
  $('hold').style.width = '0%';
  setArm(0.5);
  setStamina('stamina-me', 1);
  setStamina('stamina-rival', 1);
  $('result').hidden = true;
  $('hud').hidden = false;
}

function countdown(n) {
  clearTimeout(goTimer);
  const box = $('count');
  box.hidden = false;
  box.classList.toggle('go', n <= 0);
  $('count-n').textContent = n > 0 ? n : t('ui_go');
  if (n <= 0) goTimer = setTimeout(() => (box.hidden = true), 800);
}

function sync(data) {
  setArm(data.grade);
  setStamina('stamina-me', data.mine);
  setStamina('stamina-rival', data.theirs);
  $('hud-clock').textContent = `0:${String(Math.max(0, data.left | 0)).padStart(2, '0')}`;
}

function showResult(r) {
  $('hud').hidden = true;
  $('count').hidden = true;
  const box = $('result');
  box.className = 'result ' + r.outcome;
  $('result-title').textContent = t(r.outcome === 'win' ? 'ui_win' : r.outcome === 'lose' ? 'ui_lose' : 'ui_draw');
  $('result-reason').textContent =
    r.reason === 'forfeit'
      ? t(r.outcome === 'win' ? 'ui_reason_forfeit_win' : 'ui_reason_forfeit_lose')
      : r.reason === 'pin'
        ? t('ui_reason_pin', seconds(r.duration))
        : t('ui_reason_time');

  const lines = $('result-lines');
  lines.replaceChildren();
  const line = (label, value, className) => {
    const row = el('div', className);
    const dd = el('dd');
    if (value instanceof Node) dd.append(value);
    else dd.textContent = value;
    row.append(el('dt', null, label), dd);
    lines.append(row);
  };
  if (r.ranked && r.promoted && r.division) line(t('ui_promoted'), badge(r.division), 'up');
  if (r.ranked && r.rating != null) {
    const sign = r.delta > 0 ? '+' : '';
    line(t('ui_rating'), `${r.rating} (${sign}${r.delta})`, r.delta > 0 ? 'up' : r.delta < 0 ? 'down' : '');
    if (r.outcome === 'win' && r.streak > 1) line(t('ui_streak'), String(r.streak));
    if (r.fastest) line(t('ui_fastest_new'), seconds(r.duration), 'up');
  }
  if (r.bet > 0) {
    if (r.outcome === 'draw') line(t('ui_refund'), money(r.bet));
    else line(r.outcome === 'win' ? t('ui_won') : t('ui_lost'), money(r.bet), r.outcome === 'win' ? 'up' : 'down');
  }
  box.hidden = false;
}

function closeMatch() {
  clearTimeout(goTimer);
  $('hud').hidden = true;
  $('count').hidden = true;
  $('result').hidden = true;
}

// RANKING ----------------------------------------------------------------------------------------

function rankingRow(rank, p, className) {
  const row = el('div', 'row ' + (className || ''));
  const player = el('span', 'player');
  player.append(el('span', 'player-name', p.name ?? ''));
  const chip = badge(p.division, p.color);
  if (chip) player.append(chip);
  row.append(
    el('span', 'rank', rank ?? '—'),
    player,
    el('span', 'rating', p.rating ?? '—'),
    el('span', null, `${p.wins ?? 0} / ${p.losses ?? 0}`),
    el('span', null, p.best_streak ?? 0),
    el('span', null, p.fastest != null ? seconds(p.fastest) : '—'),
  );
  return row;
}

function openRanking(data) {
  const rows = $('board-rows');
  rows.replaceChildren();
  const top = Array.isArray(data.top) ? data.top : [];
  top.forEach((p, i) => rows.append(rankingRow(i + 1, p, i < 3 ? 'podium' : '')));
  $('board-empty').hidden = top.length > 0;
  $('board-empty-hint').textContent = t('ui_empty_first', data.minMatches ?? 3);

  const me = $('board-me');
  me.replaceChildren();
  if (data.me) {
    const mine = rankingRow(data.me.rank, { ...data.me, name: `${t('ui_me')} · ${data.name ?? ''}` }, 'me');
    me.append(mine);
    if (data.me.rank == null) me.append(el('p', 'muted note', t('ui_me_unranked', data.me.needed)));
  }
  const season = $('season');
  season.hidden = !data.season;
  if (data.season) season.textContent = t('ui_season', data.season.id, data.season.daysLeft);
  $('tabs').hidden = !data.season;
  renderHall(Array.isArray(data.hall) ? data.hall : []);
  renderTournaments(Array.isArray(data.tournaments) ? data.tournaments : []);
  showTab('season');
  rankingOpen = true;
  $('ranking').hidden = false;
}

function renderHall(hall) {
  const list = $('hall-list');
  list.replaceChildren();
  hall.forEach((entry) => {
    const block = el('section', 'hall-season');
    block.append(el('h2', null, t('ui_hall_season', entry.season)));
    entry.players.forEach((p) => {
      const row = el('div', 'row hall-row' + (p.position === 1 ? ' champion' : ''));
      row.append(
        el('span', 'rank', p.position === 1 ? '★' : p.position),
        el('span', 'player', p.name),
        el('span', 'rating', p.rating),
        el('span', null, `${p.wins} / ${p.losses}`),
      );
      block.append(row);
    });
    list.append(block);
  });
  $('hall-empty').hidden = hall.length > 0;
}

function renderTournaments(list) {
  const box = $('hall-tournament-list');
  box.replaceChildren();
  list.forEach((tour) => {
    const row = el('div', 'row hall-row tour-row');
    row.append(el('span', 'rank', '🏆'), el('span', 'player', tour.winner), el('span', 'muted', tour.name), el('span', null, money(tour.prize)));
    box.append(row);
  });
  $('hall-tournaments').hidden = list.length === 0;
  if (list.length) $('hall-empty').hidden = true;
}

// TOURNAMENT BRACKET -------------------------------------------------------------------------------

let bracketOpen = false;

function roundTitle(index, total) {
  if (index === total - 1) return t('ui_round_final');
  if (index === total - 2) return t('ui_round_semis');
  return t('ui_round', index + 1);
}

function slot(p, won, lost, bye) {
  const row = el('div', 'slot' + (won ? ' won' : '') + (lost ? ' lost' : ''));
  if (!p) {
    row.append(el('span', 'muted', bye ? t('ui_bye') : t('ui_tbd')));
    return row;
  }
  row.append(el('span', 'seed', p.seed ?? ''), el('span', 'slot-name', p.name));
  return row;
}

function openBracket(view) {
  $('bracket-name').textContent = view.name || '';
  let info;
  if (view.state === 'signup') info = t('ui_signup', `${(view.players || []).length}/${view.size}`);
  else if (view.state === 'finished' && view.champion) info = t('ui_champion', view.champion);
  else info = '';
  const prize = view.prize > 0 ? t('ui_prize', money(view.prize)) : '';
  $('bracket-info').textContent = [info, prize].filter(Boolean).join(' · ');

  const wrap = $('bracket-rounds');
  wrap.replaceChildren();
  const rounds = Array.isArray(view.rounds) ? view.rounds.slice() : [];
  // Rounds not played yet are drawn empty, so the whole bracket is visible from the start
  let size = view.bracketSize || view.size || 2;
  let total = 0;
  for (let n = size; n > 1; n /= 2) total++;
  for (let r = 0; r < total; r++) {
    const col = el('div', 'round');
    col.append(el('h2', null, roundTitle(r, total)));
    const count = size / Math.pow(2, r + 1);
    for (let i = 0; i < count; i++) {
      const m = rounds[r] && rounds[r][i];
      const card = el('div', 'match' + (m && m.live ? ' live' : ''));
      const bye = m && m.reason === 'bye';
      card.append(slot(m && m.a, m && m.winner === 'a', m && m.winner === 'b', bye), slot(m && m.b, m && m.winner === 'b', m && m.winner === 'a', bye));
      if (m && m.live) card.append(el('span', 'match-tag live', t('ui_live')));
      else if (m && m.reason === 'walkover') card.append(el('span', 'match-tag', t('ui_walkover')));
      col.append(card);
    }
    wrap.append(col);
  }
  if (view.state === 'signup') {
    const list = el('div', 'signups');
    (view.players || []).forEach((name) => list.append(el('span', 'chip', name)));
    wrap.prepend(list);
  }
  bracketOpen = true;
  $('bracket').hidden = false;
}

function closeBracket() {
  if (!bracketOpen) return;
  bracketOpen = false;
  $('bracket').hidden = true;
  post('close');
}

$('bracket-close').addEventListener('click', closeBracket);

function showTab(name) {
  document.querySelectorAll('.tab').forEach((b) => b.classList.toggle('on', b.dataset.tab === name));
  $('season-board').hidden = name !== 'season';
  $('board-me').hidden = name !== 'season';
  $('hall').hidden = name !== 'hall';
}

document.querySelectorAll('.tab').forEach((b) => b.addEventListener('click', () => showTab(b.dataset.tab)));

// SPECTATING -------------------------------------------------------------------------------------

function openSpectate(info) {
  clearTimeout(watchTimer);
  spectating = true;
  const hud = $('hud');
  hud.classList.add('spectating');
  $('hud-watching').hidden = false;
  $('hud-winner').textContent = '';
  $('hud-me').textContent = info.names?.a ?? '';
  $('hud-rival').textContent = info.names?.b ?? '';
  $('hud-pot').textContent = info.bet > 0 ? t('ui_pot', money(info.bet * 2)) : t('ui_friendly');
  $('hud-ranked').textContent = info.ranked ? t('ui_ranked') : t('ui_unranked');
  $('hud-ranked').classList.toggle('on', !!info.ranked);
  $('hud-clock').textContent = '';
  setArm(0.5);
  setStamina('stamina-me', 1);
  setStamina('stamina-rival', 1);
  hud.hidden = false;
}

function closeSpectate(winner) {
  if (!spectating) return;
  clearTimeout(watchTimer);
  if (winner) {
    $('hud-winner').textContent = ' · ' + t('ui_spectate_winner', winner);
    watchTimer = setTimeout(() => closeSpectate(), 3000);
    return;
  }
  spectating = false;
  $('hud').hidden = true;
  $('hud').classList.remove('spectating');
}

function closeRanking() {
  if (!rankingOpen) return;
  rankingOpen = false;
  $('ranking').hidden = true;
  post('close');
}

$('ranking-close').addEventListener('click', closeRanking);
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    closeRanking();
    closeBracket();
  }
});

// MESSAGES ---------------------------------------------------------------------------------------

window.addEventListener('message', ({ data }) => {
  if (!data || typeof data !== 'object') return;
  if (data.texts) applyTexts(data.texts);
  if (data.ui) applyUi(data.ui);
  switch (data.action) {
    case 'match':
      return openMatch(data.info || {});
    case 'countdown':
      return countdown(data.n);
    case 'sync':
      return sync(data);
    case 'leaving':
      return ($('hold').style.width = pct(data.progress));
    case 'result':
      return showResult(data.result || {});
    case 'matchClose':
      return closeMatch();
    case 'ranking':
      return openRanking(data);
    case 'bracket':
      return openBracket(data.view || {});
    case 'spectate':
      return openSpectate(data.info || {});
    case 'watchSync':
      return spectating && sync(data);
    case 'spectateEnd':
      return closeSpectate(data.winner);
  }
});

