			registry: (pkg) => registryJson(pkg.name, pkg.version),
			latest: async (pkg) => (await registryJson(pkg.name, "latest"))?.version,
			publish: async (pkg) => {
				console.log(`Publishing ${pkg.name}@${pkg.version}`);
				run("npm", ["publish", path.resolve(directory, pkg.file), "--access", "public", "--provenance", "--tag", "latest"]);
