                    byte[] encoded = SessionProtocol.EncodeModsManifest(localModManifest);
                    API.SendCustomEvent(CustomEvents.Hash(SessionProtocol.SessionModsReport),
                        SessionProtocol.Version, encoded);
                }
                return true;
            }
            configuredConnectRequest = null;
            return false;
        }

